(() => {
  'use strict';
  const P=window.Portal,A=P?.prototypeUsers;
  if(!P||!A||P.demoMode)return;
  const studio='https://kraftringen-provisionsstudio.hakan-rusk.chatgpt.site/';
  const allowed=()=>A.admin()&&P.role==='internal';
  P.register('commission-models',{
    render:()=>allowed()?`<div class="ow-page"><div class="page-head"><div><span class="eyebrow">KRAFTRINGEN / ADMINISTRATION</span><h1>Provisionsmodeller</h1><p>Modellversioner, simulering och historiska fakturaunderlag.</p></div><a class="btn btn-primary" href="${studio}" target="_blank" rel="noopener noreferrer">Öppna Provisionsstudion ↗</a></div><section class="card"><h2>En privat arbetsyta för provisionsmodeller</h2><p>Provisionsstudion behåller sin separata privata åtkomst. Portalens demoinloggning ger ingen tillgång till studion. Logga in med ditt behöriga ChatGPT-konto om inloggning efterfrågas.</p><p>Modellversionerna är förslag. Alla partners och avtal i studion är fiktiva och ändrar inte partnerportalens beräkningar.</p><div style="display:flex;flex-wrap:wrap;gap:10px">${[['partners','Partner & modell'],['versions','Modellversioner'],['simulation','Simulering'],['comparison','Jämför versioner'],['report','Provisionsrapport'],['tests','Beslut & tester']].map(([id,title])=>`<a class="btn btn-secondary" href="${studio}#${id}" target="_blank" rel="noopener noreferrer">${title} ↗</a>`).join('')}</div></section><section class="card"><h2>Provisionsstudio</h2><p>Om inloggningen inte fungerar i den inbäddade vyn, använd Öppna Provisionsstudion ovan.</p><iframe title="Privat Provisionsstudio – Kraftringens administration" src="${studio}" loading="lazy" referrerpolicy="strict-origin-when-cross-origin" style="display:block;width:100%;height:950px;border:1px solid #d4dfe5;border-radius:12px;background:white"></iframe></section><details class="card"><summary>Åtkomst och avgränsning i prototypen</summary><p>Detta menyval visas endast för Kraftringens administratör i intern vy. Handläggare, partners, kunder och utloggade får inte tillgång via portalens navigation. Demoroller är inte ett säkerhetsskydd: studions egen privata Sites-inloggning är den verkliga åtkomstspärren och omfattar tills vidare endast ägaren.</p><p>Fler Kraftringen-administratörer behöver uttryckligen få åtkomst med verkliga konton. Förslagen lagras fortfarande separat i studions webbläsardata. Befintliga versionsbeskrivningar, partnerordrar, provisionsberäkningar och underlag migreras inte automatiskt.</p></details></div>`:'<section class="card"><h1>Åtkomst saknas</h1><p>Provisionsmodeller är tillgängliga för Kraftringens administratörer i intern vy.</p></section>',
    bind:()=>{if(allowed()){const heading=document.querySelector('#current-page');if(heading)heading.textContent='Provisionsmodeller';}}
  });
})();
